/**
 * Copies the season catalog generated by scripts/build-cards into the app bundle, so cards
 * render instantly and offline. Run after each pipeline build.
 *
 * The app gets two layers:
 * - `src/data/cards.season1.json`: the light index (everything a card face, a list or a reveal
 *   needs). Parsed at startup.
 * - `src/data/history/chunk-NN.json`: the long-form history (story, highlights, legacy, timeline),
 *   split by collector number and only evaluated when a card's history is first opened.
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { HISTORY_CHUNK_SIZE, HISTORY_FIELDS, splitCatalog } from '../src/data/catalogSplit.ts';

const here = dirname(fileURLToPath(import.meta.url));
const source = join(here, '..', '..', 'data', 'cards.season1.json');
const dataDir = join(here, '..', 'src', 'data');
const historyDir = join(dataDir, 'history');

const catalog = JSON.parse(readFileSync(source, 'utf8')) as { cards?: Record<string, unknown>[] } & Record<string, unknown>;
if (!Array.isArray(catalog.cards) || catalog.cards.length === 0) {
  console.error(`No cards found in ${source}`);
  process.exit(1);
}

const { index, chunks } = splitCatalog(catalog as Parameters<typeof splitCatalog>[0]);

writeFileSync(join(dataDir, 'cards.season1.json'), `${JSON.stringify(index)}\n`);

mkdirSync(historyDir, { recursive: true });
for (const file of readdirSync(historyDir)) {
  if (file.startsWith('chunk-')) rmSync(join(historyDir, file));
}
const names = chunks.map((chunk, chunkIndex) => {
  const name = `chunk-${String(chunkIndex).padStart(2, '0')}.json`;
  writeFileSync(join(historyDir, name), `${JSON.stringify(chunk)}\n`);
  return name;
});

// Static requires (Metro needs literal paths), each evaluated only when its chunk is first asked for.
const loaders = names.map((name, chunkIndex) => `    case ${chunkIndex}:\n      return require('./${name}');`).join('\n');
writeFileSync(
  join(historyDir, 'chunks.generated.ts'),
  `// Generated by scripts/sync-cards.ts — do not edit.
import type { CardHistory } from '../catalogSplit';

export const HISTORY_CHUNK_COUNT = ${names.length};
export const HISTORY_CHUNK_SIZE = ${HISTORY_CHUNK_SIZE};

/** Long-form history of the cards of one chunk, keyed by card id. */
export function loadHistoryChunk(chunk: number): Record<string, CardHistory> | undefined {
  switch (chunk) {
${loaders}
    default:
      return undefined;
  }
}
`,
);

const indexKb = Math.round(JSON.stringify(index).length / 1024);
const historyKb = Math.round(chunks.reduce((total, chunk) => total + JSON.stringify(chunk).length, 0) / 1024);
console.log(
  `Synced ${catalog.cards.length} cards: index ${indexKb} KB, history ${historyKb} KB in ${names.length} chunks (${HISTORY_FIELDS.join(', ')})`,
);
